437	     */
438	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
439	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
440	
441	        try {
442	            // 예시: 로직 단순화
443	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
444	            Document doc = Jsoup.connect(url).get();
445	            // tbody#statusDetail 의 마지막 tr => 5번째 td
446	            Elements rows = doc.select("tbody#statusDetail tr");
447	            if (rows.isEmpty()) {
448	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
449	                throw new ShipmentException(
450	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
451	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
452	                );
453	            }
454	
455	            String status = rows.last().select("td").get(4).text();
456	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
457	            return status;
458	
459	        } catch (Exception e) {
460	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
461	
462	            if (e instanceof ShipmentException) {
463	                throw e;
464	            }
465	
466	            throw new ShipmentException(
467	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
468	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
469	                    e
470	            );
471	        }
472	    }
